export function tw(value: string | null | undefined): string {
  const tokens = (value ?? "").trim().split(/\s+/).filter(Boolean);
  const present = new Set(tokens);
  const output = [...tokens];
  for (const token of tokens) if (classUtilities[token]) output.push(classUtilities[token]);
  for (const [selector, utilities] of Object.entries(selectorUtilities)) {
    if (selector.split(" ").every((token) => present.has(token))) output.push(utilities);
  }
  return [...new Set(output.join(" ").split(/\s+/).filter(Boolean))].join(" ");
}
